const fs=require('fs');const{chromium}=require('playwright');const base='https://plan-ex.ru/erpv2',out=process.env.SIM_RESULT_DIR||'roles_access_simulated_result',cookie=process.env.QA_COOKIE_NAME||'',sid=process.env.QA_SIM_SESSION_ID||'';const must=(v,m)=>{if(!v)throw new Error(m)};async function noOverflow(p,w){const x=await p.evaluate(()=>({d:document.documentElement.scrollWidth-document.documentElement.clientWidth,b:document.body.scrollWidth-document.body.clientWidth,r:(()=>{const e=document.querySelector('[data-roles-access-root]');return e?e.scrollWidth-e.clientWidth:0})()}));must(x.d<=1&&x.b<=1&&x.r<=1,`overflow ${w} ${JSON.stringify(x)}`)}async function waitAssignments(p){await p.locator('[data-access-tab="assignments"]').click();for(let i=0;i<160;i++){if(await p.locator('[data-assignment-group]').count()===4)return;await p.waitForTimeout(100)}throw new Error('assignment load timeout')}async function waitBulk(g){for(let i=0;i<180;i++){if((await g.getAttribute('data-assignment-bulk-busy'))!=='1')return;await new Promise(r=>setTimeout(r,50))}throw new Error('bulk stuck')}(async()=>{fs.mkdirSync(out,{recursive:true});const b=await chromium.launch({headless:true});let writes=0,sim=0,mode='ok',reqs=[],failed='';try{const c=await b.newContext({viewport:{width:1440,height:900},locale:'ru-RU'});await c.route('**/*',async route=>{const q=route.request(),m=q.method().toUpperCase(),u=q.url();if(m==='POST'&&u.includes('/company/responsible-assignments/reassign')){sim++;const body=JSON.parse(q.postData()||'{}'),key=`${body.entity_type}:${Number(body.entity_id)}`;if(mode==='partial'){const n=reqs.length+1;reqs.push({key,ids:body.membership_ids||[]});await new Promise(r=>setTimeout(r,300));if(n===2){failed=key;return route.fulfill({status:500,contentType:'application/json',body:JSON.stringify({success:false,error:'assignment_update_failed',message:'Не удалось сохранить закрепление. Повторите позже.'})})}}return route.fulfill({status:200,contentType:'application/json',body:JSON.stringify({success:true,membership_ids:body.membership_ids||[]})})}if(!['GET','HEAD','OPTIONS'].includes(m)){writes++;return route.abort('blockedbyclient')}return route.continue()});await c.addCookies([{name:cookie,value:sid,url:base,httpOnly:true,secure:true,sameSite:'Lax'}]);const p=await c.newPage();let r=await p.goto(base+'/company/dashboard',{waitUntil:'domcontentloaded',timeout:60000});must(r&&r.status()===200,'dashboard');const up=(await c.cookies(base)).find(x=>x.name===cookie);must(up&&up.value!==sid,'sim session no rotate');fs.writeFileSync(`${out}/upgraded_sid.txt`,up.value+'\n');r=await p.goto(base+'/company/roles-access',{waitUntil:'networkidle',timeout:60000});must(r&&r.status()===200,'roles page');for(const w of[1920,1440,1366,800]){await p.setViewportSize({width:w,height:900});await p.waitForTimeout(80);await noOverflow(p,w)}await p.setViewportSize({width:1440,height:900});await waitAssignments(p);const groups=p.locator('[data-assignment-group]');let fg=null,label='',before={};for(let i=0;i<await groups.count();i++){const g=groups.nth(i),rows=g.locator('.roles-access__assignment-row');if(await rows.count()<2)continue;const d=await rows.evaluateAll(ns=>ns.map(row=>{const x=row.querySelector('input'),s=row.querySelector('span');return{label:(s?.textContent||'').trim(),key:`${x.dataset.assignmentType}:${x.dataset.assignmentId}`,checked:x.checked}}));const t=d.find(x=>!x.checked&&x.label);if(t){fg=g;label=t.label;before=Object.fromEntries(d.map(x=>[x.key,x.checked]));break}}must(fg,'no filter group');const search=fg.locator('[data-assignment-search]');await search.fill(label);await p.waitForTimeout(80);must((await fg.locator('[data-assignment-bulk="select"]').innerText()).trim()==='Выбрать найденные','select found label');must((await fg.locator('[data-assignment-bulk="clear"]').innerText()).trim()==='Снять найденные','clear found label');must(await fg.locator('.roles-access__assignment-row.is-hidden').count()>0,'no hidden rows');await fg.locator('[data-assignment-bulk="select"]').click();await waitBulk(fg);const aft=await fg.locator('.roles-access__assignment-row').evaluateAll(ns=>Object.fromEntries(ns.map(row=>{const x=row.querySelector('input');return[`${x.dataset.assignmentType}:${x.dataset.assignmentId}`,{checked:x.checked,hidden:row.classList.contains('is-hidden')}]})));for(const[k,v]of Object.entries(aft))if(v.hidden)must(v.checked===before[k],'hidden row changed '+k);await search.fill('');await p.waitForTimeout(50);must((await fg.locator('[data-assignment-bulk="select"]').innerText()).trim()==='Выбрать все','select all label');must((await fg.locator('[data-assignment-bulk="clear"]').innerText()).trim()==='Снять все','clear all label');await p.reload({waitUntil:'networkidle'});await waitAssignments(p);let pg=null,target=true,pb={};for(let i=0;i<await p.locator('[data-assignment-group]').count();i++){const g=p.locator('[data-assignment-group]').nth(i),bs=g.locator('[data-assignment-type]'),d=await bs.evaluateAll(xs=>xs.map(x=>({key:`${x.dataset.assignmentType}:${x.dataset.assignmentId}`,checked:x.checked})));if(d.length<3)continue;const u=d.filter(x=>!x.checked).length,cnt=d.filter(x=>x.checked).length;if(u>=2){pg=g;target=true;pb=Object.fromEntries(d.map(x=>[x.key,x.checked]));break}if(cnt>=2){pg=g;target=false;pb=Object.fromEntries(d.map(x=>[x.key,x.checked]));break}}must(pg,'no partial group');mode='partial';reqs=[];failed='';const act=pg.locator(`[data-assignment-bulk="${target?'select':'clear'}"]`),other=pg.locator(`[data-assignment-bulk="${target?'clear':'select'}"]`);await act.click();await p.waitForTimeout(70);must(await pg.locator('[data-assignment-bulk]').evaluateAll(bs=>bs.length===2&&bs.every(x=>x.disabled)),'both buttons not disabled');const n=reqs.length;await other.evaluate(e=>e.click());await p.waitForTimeout(70);must(reqs.length===n,'parallel bulk launched');await waitBulk(pg);must(reqs.length>=2&&failed,'partial failure not exercised');const msg=(await p.locator('[data-access-status]').innerText()).trim();must(msg===`Сохранено: ${reqs.length-1}. Не удалось: 1.`,`partial message ${msg}`);for(const q of reqs){const[t,id]=q.key.split(':'),box=pg.locator(`[data-assignment-type="${t}"][data-assignment-id="${id}"]`);must(await box.count()===1,'box missing');const chk=await box.isChecked();if(q.key===failed)must(chk===pb[q.key],'failed checkbox not rolled back');else must(chk===target,'successful simulated row not kept')}mode='ok';must(writes===0,'real writes in simulated proof '+writes);const lines=['VIEWPORTS=1920,1440,1366,800','HORIZONTAL_OVERFLOW=NO','BULK_FILTER_LABELS=PASS','FILTERED_HIDDEN_ROWS_UNCHANGED=PASS','PARTIAL_FAILURE_ROLLBACK=PASS','BULK_DOUBLE_CLICK_GUARD=PASS',`SIMULATED_WRITE_REQUESTS=${sim}`,'WRITE_REQUESTS=0','SIMULATED_BROWSER_UI_PASS=YES'];fs.writeFileSync(`${out}/proof.txt`,lines.join('\n')+'\n');lines.forEach(x=>console.log(x));await c.close()}finally{await b.close()}})().catch(e=>{console.error(e.stack||e);process.exit(1)});